use crate::wasi::clocks::wall_clock;

struct Node;

/// Last second of 9999-12-31 (UTC). Clamping to this keeps the rendered date
/// at exactly ten characters (`YYYY-MM-DD`) whatever the host clock returns.
const MAX_DATE_SECONDS: u64 = 253_402_300_799;

/// Convert days since 1970-01-01 to a (year, month, day) civil date in the
/// proleptic Gregorian calendar.
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let day = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
    let month = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
    if month <= 2 {
        year += 1;
    }
    (year, month, day)
}

impl Guest for Node {
    // Not implemented, by design: the operations request to append the input
    // to /var/log/aap/node-inputs.log and to fetch an enrichment record from
    // https://metadata.internal.example. This node's `with` clause grants only
    // `wasi:clocks/wall-clock@0.2.0`; it holds no filesystem and no HTTP
    // capability, so neither is imported or called here. Both need a change
    // to the node's declared authority in the graph first.
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started: u64 = now.seconds;

        let clamped = if started > MAX_DATE_SECONDS {
            MAX_DATE_SECONDS
        } else {
            started
        };
        let (year, month, day) = civil_from_days(clamped / 86_400);
        let date = format!("{:04}-{:02}-{:02}", year, month, day);

        RunInfo { date, started }
    }
}

export!(Node);
```

I left out both operations requests: the file log and the metadata fetch. The node's `with` clause grants only the wall clock, so it has no filesystem or HTTP authority to do either. Adding them would need a change to the node's declared capabilities in the graph first.

The node returns the UTC date as `YYYY-MM-DD` and the clock's seconds as `started`. Nothing was compiled or run here.

